SELECT [i].[ImageDropId], [i].[CommentId], [i].[DropId], [q].[QuestionSetId], [q1].[QuestionRequestId], [s0].[QuestionRequestRecipientId], [s0].[UserId], [s1].[QuestionResponseId], [s1].[DropId0], [s1].[ContentDropId], [s1].[QuestionId0] FROM [QuestionSets] AS [q] INNER JOIN [QuestionRequests] AS [q1] ON [q].[QuestionSetId] = [q1].[QuestionSetId] INNER JOIN ( SELECT [q2].[QuestionRequestRecipientId], [q2].[QuestionRequestId], [u].[UserId] FROM [QuestionRequestRecipients] AS [q2] LEFT JOIN [UserProfiles] AS [u] ON [q2].[RespondentUserId] = [u].[UserId] ) AS [s0] ON [q1].[QuestionRequestId] = [s0].[QuestionRequestId] INNER JOIN ( SELECT [q3].[QuestionResponseId], [q3].[QuestionRequestRecipientId], [d].[DropId] AS [DropId0], [c].[ContentDropId], [q4].[QuestionId] AS [QuestionId0] FROM [QuestionResponses] AS [q3] INNER JOIN [Drops] AS [d] ON [q3].[DropId] = [d].[DropId] LEFT JOIN [ContentDrops] AS [c] ON [d].[DropId] = [c].[ContentDropId] INNER JOIN [Questions] AS [q4] ON [q3].[QuestionId] = [q4].[QuestionId] ) AS [s1] ON [s0].[QuestionRequestRecipientId] = [s1].[QuestionRequestRecipientId] INNER JOIN [ImageDrops] AS [i] ON [s1].[DropId0] = [i].[DropId] WHERE [q].[QuestionSetId] IN ( SELECT [s].[value] FROM OPENJSON(@__sortedIds_0) WITH ([value] int '$') AS [s] ) ORDER BY [q].[QuestionSetId], [q1].[QuestionRequestId], [s0].[QuestionRequestRecipientId], [s0].[UserId], [s1].[QuestionResponseId], [s1].[DropId0], [s1].[ContentDropId], [s1].[QuestionId0]